func TestSSHWaitOrdersClockBeforeRuntime(t *testing.T) {
	l := nativeLab(t)
	order := []string{}
	l.wait = func(label string, _ func() (any, error), _ time.Time, _ time.Duration) (any, error) {
		order = append(order, label)
		return true, nil
	}
